"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["57954"],{92562(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.nome_tamanho","status":422,"titulo":"Nome do modelo de formul\xe1rio excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.nome_tamanho","requisitos":[],"oQueAconteceu":["O `nome` enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) tem mais de 200 caracteres, depois de aparados os espa\xe7os nas pontas.","A recusa vem na lista `errors` da resposta, com `field` igual a `nome`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado), e n\xe3o esta. S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Use um nome de at\xe9 200 caracteres. O texto mais longo vai na descri\xe7\xe3o do modelo, que aceita at\xe9 1000."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);